// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        vm.deal(address(c), 1 ether);

        bool ok;
        vm.prank(caller);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == address(this)));
    }
}
